    if now is None:
        base = datetime.now(tz=_tzinfo("UTC"))
    else:
        base = now
        if base.tzinfo is None:
            base = base.replace(tzinfo=_tzinfo("UTC"))
    return base.astimezone(_tzinfo(tz_name))
